}

async excluir(adminUserId: string, targetUserId: string) {
  if (targetUserId === adminUserId) {
    throw new BadRequestException('Você não pode excluir sua própria conta.');
  }

  const { data: perfilAntes } = await this.supabase.client
    .from('user_profiles')
    .select('email, role')
